import { expect, expectStatus, test } from "../../fixtures";

test.describe("rejecting one document sends the whole vendor back", () => {
  test("rejecting the contract extraction moves the vendor to rejected", { tag: "@LIF-02" }, async ({ factory, apiAs }) => {
    // Arrange
    const { vendor, extractions } = await factory.vendorInReview({ as: "member" });
    const reviewer = await apiAs("reviewer");

    // Act
    const response = await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
      data: { decision: "reject", note: "Wrong counterparty" },
    });

    // Assert
    const decided = await expectStatus(response, 200);
    expect(decided.status).toBe("rejected");
    expect(decided.review_note).toBe("Wrong counterparty");

    const stored = await expectStatus(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
    expect(stored.status).toBe("rejected");
  });

  test("audit trail records extraction.rejected and then vendor.rejected", { tag: "@LIF-02" }, async ({ factory, apiAs }) => {
    // Arrange
    const { vendor, extractions } = await factory.vendorInReview({ as: "member" });
    const reviewer = await apiAs("reviewer");
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
        data: { decision: "reject", note: "Wrong counterparty" },
      }),
      200,
    );

    // Act
    const trail = await expectStatus<{ items: { action: string; details: Record<string, unknown> }[] }>(
      await reviewer.get(`/api/vendors/${vendor.id}/audit`),
      200,
    );

    // Assert
    const decisionEvents = trail.items.filter((e) => ["extraction.rejected", "vendor.rejected"].includes(e.action));
    expect(decisionEvents.map((e) => e.action)).toEqual(["extraction.rejected", "vendor.rejected"]);
    expect(decisionEvents[0].details).toMatchObject({ extraction_id: extractions.contract.id, kind: "contract", note: "Wrong counterparty" });
  });
});
